const money = n => new Intl.NumberFormat('fr-FR').format(Number(n || 0)) + ' FCFA';
const subjects = ['Mathématiques','Français','Anglais','Sciences physiques','SVT','Histoire-Géographie','Philosophie','Informatique','Autres'];
const levels = ['Primaire','CI','CP','CE1','CE2','CM1','CM2','6e','5e','4e','3e','Seconde','Première','Terminale'];
const kinds = ['PDF','Vidéo','Formation','Pack','Quiz','Classe virtuelle','Autre'];
const kindEmoji = { PDF:'📘', Vidéo:'🎬', Formation:'🎓', Pack:'📚', Quiz:'🧠', 'Classe virtuelle':'🧑🏽‍🏫', Autre:'📄' };
const initialForm = { title:'', description:'', category_id:'', subject:'Mathématiques', level:'3e', kind:'PDF', price_xof:'0' };
const initials = name => (name || 'S').trim().split(/\s+/).slice(0,2).map(x=>x[0]?.toUpperCase()).join('');
const errText = error => error?.message || 'Une erreur est survenue. Réessaie.';

function Button({children,kind='primary',...props}) { return <button className={`btn ${kind}`} {...props}>{children}</button>; }
function Field({label,children,hint}) { return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>; }
function Notice({children,type='info'}) { if(!children)return null; return <div className={`notice ${type}`} role="status">{type==='error'?<AlertCircle size={17}/>:type==='success'?<CheckCircle2 size={17}/>:<CircleHelp size={17}/>}<span>{children}</span></div>; }
function Empty({icon:Icon=BookOpen,title,text,action}) { return <div className="empty"><span className="empty-icon"><Icon size={24}/></span><h3>{title}</h3><p>{text}</p>{action}</div>; }
function ProductCard({item,onOpen,onFavorite,favorite=false}) {
  const tint = ['mint','peach','lavender','sky'][String(item.id).charCodeAt(0)%4];
  return <article className="product-card">
    <button className="product-art" onClick={()=>onOpen(item)} aria-label={`Voir ${item.title}`}><span className={`art-icon ${tint}`}>{kindEmoji[item.kind]||'📘'}</span><span className="art-kind">{item.kind||'Ressource'}</span></button>
    <div className="product-content"><div className="eyebrow-row"><span>{item.subject||'Ressource'} · {item.level||'Tous niveaux'}</span><button className={`icon-button ${favorite?'active':''}`} onClick={()=>onFavorite?.(item)} aria-label="Ajouter aux favoris"><Heart size={17} fill={favorite?'currentColor':'none'}/></button></div>
      <button className="product-title" onClick={()=>onOpen(item)}>{item.title}</button><p>{item.description||'Une ressource pédagogique pour progresser.'}</p>
      <div className="teacher-line"><span className="avatar tiny">{initials(item.teacher||'Enseignant')}</span><span>{item.teacher||'Enseignant SAVOIR+'}</span></div>
      <div className="product-foot"><strong>{Number(item.price_xof)===0?'Gratuit':money(item.price_xof)}</strong><button className="text-button" onClick={()=>onOpen(item)}>Découvrir <ArrowRight size={15}/></button></div>
    </div>
  </article>;
}

export default function App() {
  const [path,setPath]=useState(window.location.pathname);
  const [session,setSession]=useState(null),[profile,setProfile]=useState(null),[role,setRole]=useState('student');
  const [products,setProducts]=useState([]),[categories,setCategories]=useState([]),[loading,setLoading]=useState(true);
  const [query,setQuery]=useState(''),[filterLevel,setFilterLevel]=useState(''),[filterSubject,setFilterSubject]=useState(''),[filterKind,setFilterKind]=useState('');
  const [selected,setSelected]=useState(null),[favoriteIds,setFavoriteIds]=useState([]),[cart,setCart]=useState([]),[notice,setNotice]=useState(''),[noticeType,setNoticeType]=useState('info');
  const [busy,setBusy]=useState(false),[mobileOpen,setMobileOpen]=useState(false),[authMode,setAuthMode]=useState('login'),[showPassword,setShowPassword]=useState(false),[signupStep,setSignupStep]=useState(1);
  const [auth,setAuth]=useState({name:'',email:'',password:'',role:'student',country:'',city:'',phone:'',learnerKind:'school_student',birthYear:'',schoolClass:'',universityYear:'',studyField:'',childClass:'',signupGoal:'',storeName:'',storeDescription:'',teacherSubjects:'',teacherLevels:'',allSubjects:false,allLevels:false});
  const [productForm,setProductForm]=useState(initialForm),[uploadFiles,setUploadFiles]=useState([]),[shareLinks,setShareLinks]=useState(null);
  const [teacherListings,setTeacherListings]=useState([]),[orders,setOrders]=useState([]),[wallet,setWallet]=useState([]),[withdrawals,setWithdrawals]=useState([]),[notifications,setNotifications]=useState([]);
  const [withdrawalForm,setWithdrawalForm]=useState({amount:'',method:'mobile_money',phone:''});
  const [adminTab,setAdminTab]=useState('overview'),[adminData,setAdminData]=useState({users:[],pending:[],orders:[],orderItems:[],walletTransactions:[],payments:[],withdrawals:[],reports:[],enrollments:[],views:[],quizAttempts:[],categories:[],actions:[]});
  const [adminFilter,setAdminFilter]=useState('pending');
  const [categoryForm,setCategoryForm]=useState({name:'',slug:'',description:''});
  const [reportOpen,setReportOpen]=useState(false),[reportForm,setReportForm]=useState({reason:'content',details:''});

  const notify=useCallback((message,type='info')=>{setNotice(message);setNoticeType(type);window.setTimeout(()=>setNotice(''),6500);},[]);
  const navigate=useCallback((to)=>{window.history.pushState({},'',to);setPath(to);setMobileOpen(false);setSelected(null);setNotice('');window.scrollTo({top:0,behavior:'smooth'});},[]);
  useEffect(()=>{const pop=()=>{setPath(window.location.pathname);setSelected(null);};window.addEventListener('popstate',pop);return()=>window.removeEventListener('popstate',pop);},[]);
  useEffect(()=>{if(!configured)return;supabase.auth.getSession().then(({data})=>setSession(data.session));const {data:{subscription}}=supabase.auth.onAuthStateChange((event,next)=>{setSession(next);if(event==='PASSWORD_RECOVERY')setAuthMode('recovery');});return()=>subscription.unsubscribe();},[]);
  useEffect(()=>{if(!session){setProfile(null);setRole('student');return;}let alive=true;Promise.all([supabase.from('profiles').select('*').eq('id',session.user.id).maybeSingle(),supabase.from('profile_details').select('*').eq('user_id',session.user.id).maybeSingle()]).then(([base,details])=>{if(!alive)return;if(base.error)notify(errText(base.error),'error');if(details.error)notify(errText(details.error),'error');const merged={...(base.data||{}),...(details.data||{})};setProfile(merged);setRole(session.user.app_metadata?.role==='savoir_admin'||session.user.app_metadata?.is_platform_owner===true?'admin':session.user.app_metadata?.role==='savoir_moderator'?'moderator':merged.account_type||'student');});return()=>{alive=false;};},[session]);
  const loadCatalog=useCallback(async()=>{if(!configured){setLoading(false);return;}setLoading(true);const [p,c]=await Promise.all([
    supabase.from('listings').select('id,title,description,subject,level,kind,price_xof,seller_id,created_at,profiles!listings_seller_id_fkey(display_name)').eq('status','approved').order('created_at',{ascending:false}).limit(60),
    supabase.from('categories').select('*').order('name')
  ]);if(p.error)notify(errText(p.error),'error');else setProducts((p.data||[]).map(x=>({...x,teacher:x.profiles?.display_name||'Enseignant SAVOIR+'})));if(c.data)setCategories(c.data);setLoading(false);},[notify]);
  useEffect(()=>{loadCatalog();},[loadCatalog]);
  useEffect(()=>{if(!session||!configured)return;const load=async()=>{
    const [f,l,o,w,wd,n]=await Promise.all([
      supabase.from('favorites').select('listing_id').eq('user_id',session.user.id),
      supabase.from('listings').select('id,title,description,subject,level,kind,price_xof,status,created_at').eq('seller_id',session.user.id).order('created_at',{ascending:false}),
      supabase.from('orders').select('id,status,subtotal_xof,created_at,order_items(id,title_snapshot,unit_price_xof,listing_id)').eq('buyer_id',session.user.id).order('created_at',{ascending:false}),
      supabase.from('wallet_transactions').select('*').eq('teacher_id',session.user.id).order('created_at',{ascending:false}),
      supabase.from('withdrawals').select('*').eq('teacher_id',session.user.id).order('created_at',{ascending:false}),
      supabase.from('notifications').select('*').eq('user_id',session.user.id).order('created_at',{ascending:false}).limit(20)
    ]);
    if(f.data)setFavoriteIds(f.data.map(x=>x.listing_id));if(l.data)setTeacherListings(l.data);if(o.data)setOrders(o.data);if(w.data)setWallet(w.data);if(wd.data)setWithdrawals(wd.data);if(n.data)setNotifications(n.data);
  };load();},[session,role]);

  useEffect(()=>{if(!configured)return;const match=path.match(/^\/(?:produit|payer)\/([0-9a-f-]{36})$/i);if(!match)return;let alive=true;supabase.from('listings').select('id,title,description,subject,level,kind,price_xof,seller_id,status,profiles!listings_seller_id_fkey(display_name)').eq('id',match[1]).eq('status','approved').maybeSingle().then(({data,error})=>{if(!alive)return;if(error||!data){notify('Ce produit est introuvable ou n’est pas publié.','error');return;}setSelected({...data,teacher:data.profiles?.display_name||'Créateur SAVOIR+'});});return()=>{alive=false;};},[path]);
  const filtered=useMemo(()=>products.filter(p=>{
    const q=query.toLocaleLowerCase('fr');
    return (!q||`${p.title} ${p.description} ${p.subject} ${p.level} ${p.teacher}`.toLocaleLowerCase('fr').includes(q))&&(!filterLevel||p.level===filterLevel)&&(!filterSubject||p.subject===filterSubject)&&(!filterKind||p.kind===filterKind);
  }),[products,query,filterLevel,filterSubject,filterKind]);
  const totalWallet=wallet.reduce((s,x)=>s+Number(x.amount_xof||0),0);
  const reservedWithdrawals=withdrawals.filter(x=>['pending','processing','paid'].includes(x.status)).reduce((s,x)=>s+Number(x.amount_xof||0),0);
  const availableWallet=Math.max(0,totalWallet-reservedWithdrawals);

  async function signUp(e){e.preventDefault();if(!configured){notify('La connexion Supabase n’est pas configurée.','error');return;}if(auth.role==='teacher'&&!auth.storeName.trim()){notify('Donne un nom à ta boutique.','error');return;}if(auth.password.length<8){notify('Choisis un mot de passe de 8 caractères minimum.','error');return;}setBusy(true);const metadata={display_name:auth.name,account_type:auth.role,country:auth.country.trim()||'Non précisé',city:auth.city,phone:auth.phone,learner_kind:auth.learnerKind,birth_year:auth.birthYear||null,school_class:auth.schoolClass,university_year:auth.universityYear,study_field:auth.studyField,child_class:auth.childClass,signup_goal:auth.signupGoal,store_name:auth.storeName,store_description:auth.storeDescription,teacher_headline:auth.storeDescription,teacher_subjects:auth.allSubjects?'Toutes les matières':auth.teacherSubjects,teacher_levels:auth.allLevels?'Tous niveaux':auth.teacherLevels,all_subjects:auth.allSubjects,all_levels:auth.allLevels};const {error}=await supabase.auth.signUp({email:auth.email,password:auth.password,options:{data:metadata}});setBusy(false);if(error)notify(errText(error),'error');else{notify('Compte créé. Ton espace SAVOIR+ est prêt dès ta première connexion.','success');setAuthMode('login');setSignupStep(1);}}
  async function signIn(e){e.preventDefault();if(!configured){notify('La connexion Supabase n’est pas configurée.','error');return;}setBusy(true);const {error}=await supabase.auth.signInWithPassword({email:auth.email,password:auth.password});setBusy(false);if(error)notify(errText(error),'error');else navigate('/mon-espace');}
  async function sendPasswordReset(e){e.preventDefault();if(!configured)return;setBusy(true);const {error}=await supabase.auth.resetPasswordForEmail(auth.email,{redirectTo:window.location.origin+'/connexion'});setBusy(false);if(error)notify(errText(error),'error');else notify('Un lien de réinitialisation a été envoyé si cette adresse possède un compte.','success');}
  async function completePasswordReset(e){e.preventDefault();if(auth.password.length<8){notify('Le nouveau mot de passe doit contenir au moins 8 caractères.','error');return;}setBusy(true);const {error}=await supabase.auth.updateUser({password:auth.password});setBusy(false);if(error)notify(errText(error),'error');else{notify('Mot de passe mis à jour. Tu peux maintenant te connecter.','success');setAuthMode('login');setAuth(x=>({...x,password:''}));navigate('/connexion');}}
  async function signOut(){await supabase.auth.signOut();setSession(null);setProfile(null);navigate('/');}
  async function toggleFavorite(item){if(!session){notify('Connecte-toi pour enregistrer tes favoris.');navigate('/connexion');return;}const exists=favoriteIds.includes(item.id);const result=exists?await supabase.from('favorites').delete().eq('user_id',session.user.id).eq('listing_id',item.id):await supabase.from('favorites').insert({user_id:session.user.id,listing_id:item.id});if(result.error)notify(errText(result.error),'error');else setFavoriteIds(old=>exists?old.filter(x=>x!==item.id):[...old,item.id]);}
  async function createListing(e){
    e.preventDefault();
    if(!session||(role!=='teacher'&&role!=='admin')){notify('Un compte créateur est nécessaire.','error');navigate('/connexion');return;}
    if(!productForm.title.trim()||!productForm.description.trim()||Number(productForm.price_xof)<0){notify('Vérifie les informations du produit.','error');return;}
    const pdfs=uploadFiles.filter(x=>x.type==='application/pdf');
    const videos=uploadFiles.filter(x=>x.type==='video/mp4');
    if(uploadFiles.length===0){notify('Ajoute au moins un fichier PDF ou une vidéo MP4.','error');return;}
    if(uploadFiles.some(x=>!['application/pdf','video/mp4'].includes(x.type))){notify('Seuls les fichiers PDF et les vidéos MP4 sont acceptés.','error');return;}
    if(pdfs.length>20){notify('Maximum autorisé : 20 fichiers PDF par produit.','error');return;}
    if(videos.length>10){notify('Maximum autorisé : 10 vidéos MP4 par produit.','error');return;}
    if(uploadFiles.some(x=>x.size>100*1024*1024)){notify('Chaque fichier doit faire 100 Mo maximum.','error');return;}
    setBusy(true);
    const payload={seller_id:session.user.id,title:productForm.title.trim(),description:productForm.description.trim(),category_id:productForm.category_id||null,subject:productForm.subject,level:productForm.level,kind:pdfs.length&&videos.length?'Formation':videos.length?'Vidéo':'PDF',listing_type:videos.length?'course':'document',price_xof:Number(productForm.price_xof),status:'draft'};
    const {data,error}=await supabase.from('listings').insert(payload).select('id').single();
    if(error){setBusy(false);notify(errText(error),'error');return;}
    const uploadedPaths=[];
    for(const file of uploadFiles){
      const path=`${data.id}/${crypto.randomUUID()}-${file.name.replace(/[^a-zA-Z0-9._-]/g,'_')}`;
      const uploaded=await supabase.storage.from('savoir-products').upload(path,file,{contentType:file.type,upsert:false});
      if(uploaded.error){
        if(uploadedPaths.length)await supabase.storage.from('savoir-products').remove(uploadedPaths);
        await supabase.from('listings').delete().eq('id',data.id);
        setBusy(false);notify(`Envoi interrompu pour ${file.name} : ${errText(uploaded.error)}. Aucun produit incomplet n'a été publié.`,'error');return;
      }
      uploadedPaths.push(path);
      const saved=await supabase.from('product_files').insert({listing_id:data.id,storage_path:path,original_name:file.name,mime_type:file.type,file_size_bytes:file.size,is_preview:false});
      if(saved.error){
        await supabase.storage.from('savoir-products').remove(uploadedPaths);
        await supabase.from('listings').delete().eq('id',data.id);
        setBusy(false);notify(`Enregistrement du fichier ${file.name} impossible : ${errText(saved.error)}. Le produit incomplet a été annulé.`,'error');return;
      }
    }
    const {error:publishError}=await supabase.rpc('publish_savoir_listing',{p_listing_id:data.id});
    if(publishError){
      await supabase.storage.from('savoir-products').remove(uploadedPaths);
      await supabase.from('listings').delete().eq('id',data.id);
      setBusy(false);notify(`Publication impossible : ${errText(publishError)}. Le produit incomplet a été annulé.`,'error');return;
    }
    const links={preview:`${window.location.origin}/produit/${data.id}`,payment:`${window.location.origin}/payer/${data.id}`};
    setBusy(false);setProductForm(initialForm);setUploadFiles([]);setShareLinks({id:data.id,...links});
    notify('Produit créé et fichiers enregistrés. Les liens de partage sont prêts.','success');
  }
  async function createOrder(item){if(!session){notify('Connecte-toi pour accéder à cette ressource.');navigate('/connexion');return;}if(item.seller_id===session.user.id){notify('Tu ne peux pas rejoindre ta propre ressource.','error');return;}if(Number(item.price_xof)>0){notify('Cette ressource est payante. L’achat sera disponible après la configuration du paiement.','error');return;}setBusy(true);const {error}=await supabase.rpc('enroll_free_listing',{p_listing_id:item.id});setBusy(false);if(error){notify(errText(error),'error');return;}setSelected(null);notify('Inscription gratuite confirmée. Bonne formation !','success');navigate(`/apprendre/${item.id}`);}
  async function downloadResource(listingId){if(!session){navigate('/connexion');return;}setBusy(true);const {data,error}=await supabase.functions.invoke('savoir-product-download',{body:{listing_id:listingId}});setBusy(false);if(error||!data?.url){notify(data?.error||errText(error),'error');return;}window.open(data.url,'_blank','noopener,noreferrer');}
  async function requestWithdrawal(e){e.preventDefault();if(!session||role!=='teacher')return;const amount=Number(withdrawalForm.amount);if(!Number.isInteger(amount)||amount<1000){notify('Le montant minimum de retrait est de 1 000 FCFA.','error');return;}if(withdrawalForm.method==='mobile_money'&&withdrawalForm.phone.replace(/\D/g,'').length<8){notify('Renseigne un numéro Mobile Money valide.','error');return;}setBusy(true);const {error}=await supabase.rpc('request_withdrawal',{p_amount_xof:amount,p_payout_method:withdrawalForm.method,p_payout_details:withdrawalForm.method==='mobile_money'?{phone:withdrawalForm.phone}:{account:withdrawalForm.phone}});setBusy(false);if(error)notify(errText(error),'error');else{notify('Demande de retrait envoyée à l’administration.','success');setWithdrawalForm({amount:'',method:'mobile_money',phone:''});const {data}=await supabase.from('withdrawals').select('*').eq('teacher_id',session.user.id).order('created_at',{ascending:false});if(data)setWithdrawals(data);}}
  async function updateWithdrawal(id,status){const {error}=await supabase.rpc('admin_update_withdrawal',{p_withdrawal_id:id,p_status:status,p_note:''});if(error)notify(errText(error),'error');else{notify('Statut du retrait mis à jour.','success');loadAdmin();}}
  async function loadAdmin(){if(!session||role!=='admin'){notify('Accès réservé à l’administration.','error');return;}const [u,p,o,pa,w,r,en,v,qa,c,a]=await Promise.all([
    supabase.from('admin_user_directory').select('user_id,email,account_type,app_role,created_at,display_name,country,city,phone,learner_kind,birth_year,school_class,university_year,study_field,child_class,signup_goal,birth_year,store_name,store_description,teacher_subjects,teacher_levels').order('created_at',{ascending:false}).limit(500),
    supabase.from('listings').select('id,title,description,subject,level,kind,price_xof,seller_id,status,created_at,profiles!listings_seller_id_fkey(display_name)').order('created_at',{ascending:false}),
    supabase.from('orders').select('id,buyer_id,status,subtotal_xof,created_at').order('created_at',{ascending:false}).limit(500),
    supabase.from('payments').select('*').order('created_at',{ascending:false}).limit(500),
    supabase.from('withdrawals').select('*').order('created_at',{ascending:false}).limit(500),
    supabase.from('reports').select('*').order('created_at',{ascending:false}).limit(500),
    supabase.from('enrollments').select('id,learner_id,listing_id,status,source,enrolled_at,profiles!enrollments_learner_id_fkey(display_name),listings!enrollments_listing_id_fkey(title)').order('enrolled_at',{ascending:false}).limit(500),
    supabase.from('listing_views').select('id,listing_id,viewer_id,viewed_on,listings!listing_views_listing_id_fkey(title)').order('created_at',{ascending:false}).limit(500),
    supabase.from('quiz_attempts').select('id,quiz_id,learner_id,percentage,passed,submitted_at,quizzes!quiz_attempts_quiz_id_fkey(title),profiles!quiz_attempts_learner_id_fkey(display_name)').order('submitted_at',{ascending:false}).limit(500),
    supabase.from('categories').select('*').order('name'),
    supabase.from('admin_actions').select('id,action,target_type,target_id,details,created_at,profiles!admin_actions_admin_id_fkey(display_name)').order('created_at',{ascending:false}).limit(200)
  ]);const [oi,wt]=await Promise.all([supabase.from('order_items').select('id,order_id,seller_id,title_snapshot,unit_price_xof,teacher_amount_xof'),supabase.from('wallet_transactions').select('teacher_id,amount_xof,transaction_type,created_at')]);const errors=[u,p,o,pa,w,r,en,v,qa,c,a,oi,wt].filter(x=>x.error);if(errors.length)notify(`Certaines données admin ne sont pas accessibles : ${errText(errors[0].error)}`,'error');setAdminData({users:u.data||[],pending:p.data||[],orders:o.data||[],orderItems:oi.data||[],walletTransactions:wt.data||[],payments:pa.data||[],withdrawals:w.data||[],reports:r.data||[],enrollments:en.data||[],views:v.data||[],quizAttempts:qa.data||[],categories:c.data||[],actions:a.data||[]});}
  async function createCategory(e){e.preventDefault();if(!categoryForm.name.trim())return;const slug=(categoryForm.slug||categoryForm.name).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');const {error}=await supabase.from('categories').insert({name:categoryForm.name.trim(),slug,description:categoryForm.description.trim()});if(error)notify(errText(error),'error');else{notify('Catégorie créée.','success');setCategoryForm({name:'',slug:'',description:''});loadAdmin();}}
  async function deleteCategory(id){const {error}=await supabase.from('categories').delete().eq('id',id);if(error)notify(errText(error),'error');else{notify('Catégorie supprimée.','success');loadAdmin();}}
  async function promoteAdmin(userId){if(!session?.user?.app_metadata?.is_platform_owner){notify('Seul le propriétaire peut nommer un administrateur.','error');return;}const {error}=await supabase.rpc('promote_savoir_admin',{p_user_id:userId});if(error)notify(errText(error),'error');else{notify('Administrateur nommé. Il devra se reconnecter pour actualiser son rôle.','success');loadAdmin();}}
  async function moderateReport(id,status){const {error}=await supabase.from('reports').update({status,reviewed_by:session.user.id}).eq('id',id);if(error)notify(errText(error),'error');else{notify('Signalement mis à jour.','success');loadAdmin();}}
  async function submitReport(e){e.preventDefault();if(!session){notify('Connecte-toi pour signaler une ressource.','error');navigate('/connexion');return;}if(!selected)return;setBusy(true);const {error}=await supabase.from('reports').insert({reporter_id:session.user.id,listing_id:selected.id,reason:reportForm.reason,details:reportForm.details.trim()});setBusy(false);if(error)notify(errText(error),'error');else{notify('Signalement envoyé à la modération.','success');setReportOpen(false);setReportForm({reason:'content',details:''});}}
  useEffect(()=>{if(path==='/admin'&&session&&role==='admin')loadAdmin();},[path,session,role]);
  async function moderate(id,status){const {error}=await supabase.rpc('admin_moderate_listing',{p_listing_id:id,p_status:status,p_note:''});if(error)notify(errText(error),'error');else{notify(status==='approved'?'Ressource publiée.':'Ressource refusée.','success');loadAdmin();loadCatalog();}}
  async function markNotification(id){const {error}=await supabase.from('notifications').update({read_at:new Date().toISOString()}).eq('id',id);if(!error)setNotifications(n=>n.map(x=>x.id===id?{...x,read_at:new Date().toISOString()}:x));}

  function openProduct(item){setSelected(item);if(session&&item.seller_id!==session.user.id)supabase.rpc('record_listing_view',{p_listing_id:item.id});window.scrollTo({top:0,behavior:'smooth'});}
  const routePath=path.split('?')[0];
  const currentPage=routePath.startsWith('/produit/')||routePath.startsWith('/payer/')?'shared-product':routePath==='/admin'?'admin':routePath==='/connexion'?'auth':routePath==='/explorer'?'market':routePath==='/devenir-enseignant'?'create':routePath==='/mon-espace'?'dashboard':routePath==='/bibliotheque'?'library':routePath==='/favoris'?'favorites':routePath==='/notifications'?'notifications':routePath==='/mes-cours'?'studio':routePath==='/parents'?'parents':routePath==='/messages'?'messages':routePath==='/profil-enseignant'?'teacher-profile':routePath==='/enseignants'?'teachers':routePath.startsWith('/apprendre/')?'course':routePath.startsWith('/suivi/')?'child-progress':routePath.startsWith('/boutique/')?'store':'home';
  const admin=role==='admin';
  const isPlatformOwner=session?.user?.app_metadata?.is_platform_owner===true;
  function startSignup(role,learnerKind='school_student'){setAuth(x=>({...x,role,learnerKind}));setSignupStep(2);setAuthMode('signup');navigate('/connexion');}

  return <div className="app-shell">
    <header className="site-header"><div className="header-inner">
      <button className="brand" onClick={()=>navigate('/')}><span className="brand-symbol">S+</span><span>SAVOIR<span className="brand-plus">+</span><small>APPRENDRE · CRÉER · PROGRESSER</small></span></button>
      <button className="mobile-toggle" onClick={()=>setMobileOpen(v=>!v)} aria-label="Menu">{mobileOpen?<X/>:<Menu/>}</button>
      <nav className={`main-nav ${mobileOpen?'show':''}`}>{!session?<><button onClick={()=>navigate('/')}>Accueil</button><button onClick={()=>navigate('/explorer')}>Explorer</button><button onClick={()=>navigate('/enseignants')}>Créateurs</button><button onClick={()=>navigate('/devenir-enseignant')}>Devenir créateur</button></>:role==='admin'?<><button onClick={()=>navigate('/admin')}>Administration</button><button onClick={()=>navigate('/explorer')}>Marketplace</button>{profile?.account_type==='teacher'&&<button onClick={()=>navigate('/mon-espace')}>Ma boutique</button>}</>:role==='teacher'?<><button onClick={()=>navigate('/mon-espace')}>Ma boutique</button><button onClick={()=>navigate('/mes-cours')}>Mes ressources</button><button onClick={()=>navigate('/profil-enseignant')}>Profil de ma boutique</button><button onClick={()=>navigate('/messages')}>Messages clients</button></>:role==='parent'?<><button onClick={()=>navigate('/mon-espace')}>Mon espace parent</button><button onClick={()=>navigate('/explorer')}>Explorer les ressources</button><button onClick={()=>navigate('/parents')}>Mes enfants</button></>:<><button onClick={()=>navigate('/mon-espace')}>Mon espace</button><button onClick={()=>navigate('/explorer')}>Explorer</button><button onClick={()=>navigate('/bibliotheque')}>Ma bibliothèque</button><button onClick={()=>navigate('/favoris')}>Mes favoris</button></>}</nav>
      <div className="header-actions">{session?<><button className="header-link" onClick={()=>navigate('/notifications')}><Bell size={17}/>{notifications.some(n=>!n.read_at)&&<i/>}</button><button className="btn btn-soft btn-sm" onClick={()=>navigate('/mon-espace')}><LayoutDashboard size={16}/> Mon espace</button><button className="icon-button" onClick={signOut} title="Déconnexion"><LogOut size={17}/></button></>:<><Button kind="btn-outline btn-sm" onClick={()=>{setAuthMode('signup');setSignupStep(1);navigate('/connexion');}}>S’inscrire</Button><Button kind="btn-primary btn-sm" onClick={()=>{setAuthMode('login');navigate('/connexion');}}>Connexion <ArrowRight size={16}/></Button></>}</div>
    </div></header>
    {notice&&<div className="toast-wrap"><Notice type={noticeType}>{notice}</Notice></div>}

    {currentPage==='home'&&<>
      <section className="hero"><div className="container hero-layout"><div className="hero-copy"><span className="eyebrow"><Sparkles size={14}/> LE SAVOIR PREND UNE NOUVELLE DIMENSION</span><h1>Votre savoir<br/><em>a plus de valeur.</em></h1><p>Découvrez des ressources conçues par des enseignants. Apprenez à votre rythme ou transformez votre expertise pédagogique en revenus.</p><div className="hero-actions audience-actions"><Button onClick={()=>startSignup('student','school_student')}><BookOpen size={17}/> Je suis élève</Button><Button kind="btn-outline" onClick={()=>startSignup('student','university_student')}><GraduationCap size={17}/> Je suis étudiant</Button><Button kind="btn-outline" onClick={()=>startSignup('parent')}><Users size={17}/> Je suis parent</Button><Button kind="btn-gold" onClick={()=>startSignup('teacher')}><UserRound size={17}/> Je suis créateur</Button></div><div className="hero-proof"><span><ShieldCheck size={16}/> Un espace adapté à chaque profil</span><span><Users size={16}/> Ouvert à tous les pays</span></div></div>
        <div className="hero-visual"><div className="visual-glow"/><div className="visual-main"><div className="visual-top"><span className="visual-label">APPRENDRE AUTREMENT</span><span className="visual-stars">✦ ✦ ✦</span></div><div className="book-stack"><div className="book book-one"><span>SCIENCES</span><b>Comprendre<br/>le monde</b><small>SAVOIR+</small></div><div className="book book-two"><span>MATHÉMATIQUES</span><b>Réussir<br/>ses exercices</b><small>SAVOIR+</small></div><div className="book book-three"><span>LANGUES</span><b>Pratiquer<br/>chaque jour</b><small>SAVOIR+</small></div></div><div className="visual-bottom"><div><strong>Le savoir se partage.</strong><small>Et il crée des opportunités.</small></div><span className="visual-arrow"><ArrowRight size={20}/></span></div></div><div className="floating-note note-top"><span>✦</span> Apprendre à son rythme</div><div className="floating-note note-bottom"><span>✓</span> Créé par des enseignants</div></div>
      </div></section>
      <section className="benefit-strip"><div className="container benefit-grid"><div><BookOpen/><b>Apprendre</b><span>Des ressources adaptées</span></div><div><GraduationCap/><b>Enseigner</b><span>Valoriser son expertise</span></div><div><TrendingUp/><b>Développer</b><span>Créer de nouvelles opportunités</span></div><div><ShieldCheck/><b>En confiance</b><span>Un espace encadré</span></div></div></section><section className="section audience-section"><div className="container"><div className="section-heading"><div><span className="eyebrow">UN ESPACE POUR CHACUN</span><h2>Choisissez votre parcours.</h2><p>Que vous souhaitiez apprendre, accompagner un enfant ou vendre votre expertise, SAVOIR+ vous guide vers les bons outils.</p></div></div><div className="audience-grid"><article className="audience-card"><BookOpen/><h3>Élèves</h3><p>Retrouvez des cours, fiches et exercices adaptés à votre classe pour progresser à votre rythme.</p><button className="text-button" onClick={()=>startSignup('student','school_student')}>Créer mon compte élève <ArrowRight size={15}/></button></article><article className="audience-card"><GraduationCap/><h3>Étudiants</h3><p>Explorez des ressources liées à votre filière et à votre niveau universitaire.</p><button className="text-button" onClick={()=>startSignup('student','university_student')}>Créer mon compte étudiant <ArrowRight size={15}/></button></article><article className="audience-card"><Users/><h3>Parents</h3><p>Accompagnez la scolarité de votre enfant et suivez sa progression avec son accord.</p><button className="text-button" onClick={()=>startSignup('parent')}>Créer mon compte parent <ArrowRight size={15}/></button></article><article className="audience-card"><UserRound/><h3>Créateurs</h3><p>Ouvrez votre boutique, publiez vos ressources et développez votre activité pédagogique.</p><button className="text-button" onClick={()=>startSignup('teacher')}>Ouvrir ma boutique <ArrowRight size={15}/></button></article></div></div></section>
      <section className="section"><div className="container"><div className="section-heading"><div><span className="eyebrow">LA SÉLECTION SAVOIR+</span><h2>Explorez les ressources</h2><p>Des contenus pédagogiques pour avancer avec méthode.</p></div><button className="text-button" onClick={()=>navigate('/explorer')}>Tout explorer <ArrowRight size={16}/></button></div>
        {loading?<div className="loading-grid">{[1,2,3].map(x=><div className="skeleton" key={x}/>)}</div>:products.length?<div className="product-grid">{products.slice(0,3).map(p=><ProductCard key={p.id} item={p} onOpen={openProduct} onFavorite={toggleFavorite} favorite={favoriteIds.includes(p.id)}/>)}</div>:<Empty icon={BookOpen} title="Les premières ressources arrivent" text="Les enseignants pourront bientôt publier leurs cours, fiches et formations sur SAVOIR+." action={<Button kind="btn-outline" onClick={()=>navigate('/devenir-enseignant')}>Devenir créateur</Button>}/>}</div></section>
      <section className="creator-band"><div className="container creator-band-inner"><div><span className="eyebrow light">VOUS ÊTES ENSEIGNANT ?</span><h2>Votre expertise mérite<br/>d’aller plus loin.</h2><p>Créez des ressources, faites-les découvrir et développez votre activité numérique.</p><Button kind="btn-gold" onClick={()=>navigate('/devenir-enseignant')}>Rejoindre les créateurs <ArrowRight size={17}/></Button></div><div className="creator-art"><div className="creator-orbit orbit-one"/><div className="creator-orbit orbit-two"/><div className="creator-center"><GraduationCap size={52}/></div><span className="orbit-tag tag-a">Créer</span><span className="orbit-tag tag-b">Partager</span><span className="orbit-tag tag-c">Progresser</span></div></div></section>
    </>}

    {currentPage==='market'&&<main className="container page-main"><div className="page-intro"><span className="eyebrow">MARKETPLACE</span><h1>Trouvez votre prochaine ressource.</h1><p>Explorez les ressources pédagogiques disponibles sur SAVOIR+.</p></div><div className="filters-panel"><div className="search-field"><Search size={18}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Rechercher un cours, une matière, un niveau…"/></div><select value={filterSubject} onChange={e=>setFilterSubject(e.target.value)}><option value="">Toutes les matières</option>{subjects.map(s=><option key={s}>{s}</option>)}</select><select value={filterLevel} onChange={e=>setFilterLevel(e.target.value)}><option value="">Tous les niveaux</option>{levels.map(s=><option key={s}>{s}</option>)}</select><select value={filterKind} onChange={e=>setFilterKind(e.target.value)}><option value="">Tous les formats</option>{kinds.map(s=><option key={s}>{s}</option>)}</select></div><div className="result-count"><span>{filtered.length} ressource(s)</span><button className="text-button" onClick={()=>{setQuery('');setFilterSubject('');setFilterLevel('');setFilterKind('');}}>Réinitialiser les filtres</button></div>{loading?<div className="loading-grid">{[1,2,3].map(x=><div className="skeleton" key={x}/>)}</div>:filtered.length?<div className="product-grid">{filtered.map(p=><ProductCard key={p.id} item={p} onOpen={openProduct} onFavorite={toggleFavorite} favorite={favoriteIds.includes(p.id)}/>)}</div>:<Empty icon={Search} title="Aucun résultat" text="Essaie un autre mot-clé ou enlève certains filtres."/>}</main>}

    {currentPage==='auth'&&<main className="container auth-page"><div className="auth-aside"><span className="eyebrow light">BIENVENUE SUR SAVOIR+</span><h1>Le savoir grandit<br/>quand il se partage.</h1><p>Un espace pour apprendre, enseigner et donner plus de valeur aux connaissances.</p><div className="auth-illustration"><BookOpen size={60}/><GraduationCap size={45}/><Sparkles size={26}/></div></div><div className="auth-card">{authMode!=='recovery'&&authMode!=='reset'&&<div className="auth-tabs"><button className={authMode==='login'?'selected':''} onClick={()=>{setAuthMode('login');setShowPassword(false);}}>Connexion</button><button className={authMode==='signup'?'selected':''} onClick={()=>{setAuthMode('signup');setSignupStep(1);setShowPassword(false);}}>S’inscrire</button></div>}<h2>{authMode==='login'?'Ravi de te revoir':authMode==='signup'?'Rejoins SAVOIR+':authMode==='reset'?'Récupérer mon accès':'Choisir un nouveau mot de passe'}</h2><p>{authMode==='login'?'Connecte-toi pour retrouver ton espace.':authMode==='signup'?'Choisis ton profil et commence ton parcours.':authMode==='reset'?'Nous t’enverrons un lien sécurisé par e-mail.':'Définis un nouveau mot de passe pour ton compte.'}</p><form className="form-stack" onSubmit={authMode==='login'?signIn:authMode==='signup'?signUp:authMode==='reset'?sendPasswordReset:completePasswordReset}>{authMode==='signup'&&<>{signupStep===1?<div className="signup-step"><span className="eyebrow">ÉTAPE 1 SUR 2 · CHOISIS TON PROFIL</span><div className="role-choice-grid"><button type="button" className={auth.role==='student'&&auth.learnerKind==='school_student'?'role-choice selected':''} onClick={()=>setAuth({...auth,role:'student',learnerKind:'school_student'})}><BookOpen/><b>Je suis élève</b><small>Primaire, collège ou lycée</small></button><button type="button" className={auth.role==='student'&&auth.learnerKind==='university_student'?'role-choice selected':''} onClick={()=>setAuth({...auth,role:'student',learnerKind:'university_student'})}><GraduationCap/><b>Je suis étudiant</b><small>Université, master ou doctorat</small></button><button type="button" className={auth.role==='parent'?'role-choice selected':''} onClick={()=>setAuth({...auth,role:'parent'})}><Users/><b>Je suis parent</b><small>Suivre la scolarité de mon enfant</small></button><button type="button" className={auth.role==='teacher'?'role-choice selected':''} onClick={()=>setAuth({...auth,role:'teacher'})}><UserRound/><b>Je suis créateur</b><small>Ouvrir ma boutique et vendre mes ressources</small></button></div><Button type="button" disabled={busy} onClick={()=>setSignupStep(2)}>Suivant <ArrowRight size={17}/></Button></div>:<div className="signup-details"><div className="signup-step-heading"><span className="eyebrow">ÉTAPE 2 SUR 2 · TES INFORMATIONS</span><button type="button" className="text-button" onClick={()=>setSignupStep(1)}>← Modifier mon profil</button></div><Field label="Nom complet"><input required minLength="2" value={auth.name} onChange={e=>setAuth({...auth,name:e.target.value})} placeholder="Ton nom et prénom"/></Field>{auth.role==='student'&&<><Field label="Parcours"><select value={auth.learnerKind} onChange={e=>setAuth({...auth,learnerKind:e.target.value})}><option value="school_student">Élève · Primaire, collège ou lycée</option><option value="university_student">Étudiant · Université</option></select></Field>{auth.learnerKind==='school_student'?<Field label="Classe actuelle (facultatif)"><input value={auth.schoolClass} onChange={e=>setAuth({...auth,schoolClass:e.target.value})} placeholder="Ex. CM2, 3e, Terminale…"/></Field>:<div className="two-fields"><Field label="Année universitaire (facultatif)"><input value={auth.universityYear} onChange={e=>setAuth({...auth,universityYear:e.target.value})} placeholder="Ex. Licence 1, Master 2, Doctorat…"/></Field><Field label="Filière (facultatif)"><input value={auth.studyField} onChange={e=>setAuth({...auth,studyField:e.target.value})} placeholder="Ex. Droit, Informatique…"/></Field></div>}<Field label="Année de naissance (facultatif)"><input type="number" min="1900" max="2026" value={auth.birthYear} onChange={e=>setAuth({...auth,birthYear:e.target.value})} placeholder="Ex. 2010"/></Field></>}{auth.role==='parent'&&<Field label="Classe actuelle de ton enfant (facultatif)"><input value={auth.childClass} onChange={e=>setAuth({...auth,childClass:e.target.value})} placeholder="Ex. CE2, 6e, Première…"/></Field>}{auth.role==='teacher'&&<><Field label="Nom de ta boutique"><input required maxLength="100" value={auth.storeName} onChange={e=>setAuth({...auth,storeName:e.target.value})} placeholder="Ex. La boutique des sciences"/></Field><Field label="Que souhaites-tu vendre ? / Présentation de ta boutique"><textarea required rows="3" maxLength="1200" value={auth.storeDescription} onChange={e=>setAuth({...auth,storeDescription:e.target.value})} placeholder="Ex. fiches de cours, exercices corrigés, vidéos, formations…"/></Field><Field label="Matières de spécialisation" hint="Choisis une matière proposée ou écris librement si elle n’apparaît pas."><input list="savoir-subject-options" disabled={auth.allSubjects} value={auth.teacherSubjects} onChange={e=>setAuth({...auth,teacherSubjects:e.target.value})} placeholder="Choisir ou saisir une matière…"/><datalist id="savoir-subject-options">{subjects.map(subject=><option key={subject} value={subject}/>)}</datalist></Field><label className="check-line"><input type="checkbox" checked={auth.allSubjects} onChange={e=>setAuth({...auth,allSubjects:e.target.checked})}/> Toutes les matières</label><Field label="Classes / niveaux de spécialisation" hint="Tu peux écrire plusieurs niveaux ou choisir Tous les niveaux."><input list="savoir-level-options" disabled={auth.allLevels} value={auth.teacherLevels} onChange={e=>setAuth({...auth,teacherLevels:e.target.value})} placeholder="Choisir ou saisir un niveau…"/><datalist id="savoir-level-options">{levels.map(level=><option key={level} value={level}/>)}</datalist></Field><label className="check-line"><input type="checkbox" checked={auth.allLevels} onChange={e=>setAuth({...auth,allLevels:e.target.checked})}/> Tous les niveaux</label></>}<Field label={auth.role==='teacher'?"Ton objectif sur SAVOIR+ (facultatif)":"Pourquoi viens-tu sur SAVOIR+ ? (facultatif)"}><textarea rows="2" maxLength="1000" value={auth.signupGoal} onChange={e=>setAuth({...auth,signupGoal:e.target.value})} placeholder={auth.role==='teacher'?"Tes objectifs pour ta boutique et tes apprenants…":"Tes objectifs, les matières ou les ressources recherchées…"}/></Field><div className="two-fields"><Field label="Téléphone (facultatif)"><input type="tel" value={auth.phone} onChange={e=>setAuth({...auth,phone:e.target.value})} placeholder="+229…"/></Field><Field label="Ville (facultatif)"><input value={auth.city} onChange={e=>setAuth({...auth,city:e.target.value})} placeholder="Ville"/></Field></div><Field label="Pays" hint="SAVOIR+ est ouvert aux utilisateurs de tous les pays."><input autoComplete="country-name" value={auth.country} onChange={e=>setAuth({...auth,country:e.target.value})} placeholder="Ex. Bénin, France, Canada…"/></Field></div>}</>}{(authMode!=='recovery'&&(authMode!=='signup'||signupStep===2))&&<Field label="Adresse e-mail"><input required type="email" autoComplete="email" value={auth.email} onChange={e=>setAuth({...auth,email:e.target.value})} placeholder="nom@exemple.com"/></Field>}{authMode!=='reset'&&authMode!=='recovery'&&(authMode!=='signup'||signupStep===2)&&<Field label="Mot de passe"><div className="password-control"><input required type={showPassword?"text":"password"} minLength="8" autoComplete={authMode==='login'?'current-password':'new-password'} value={auth.password} onChange={e=>setAuth({...auth,password:e.target.value})} placeholder="8 caractères minimum"/><button type="button" className="password-visibility" onClick={()=>setShowPassword(v=>!v)} aria-label={showPassword?"Masquer le mot de passe":"Afficher le mot de passe"} aria-pressed={showPassword}>{showPassword?<EyeOff size={18}/>:<Eye size={18}/>}</button></div></Field>}{authMode==='recovery'&&<Field label="Nouveau mot de passe"><div className="password-control"><input required type={showPassword?"text":"password"} minLength="8" autoComplete="new-password" value={auth.password} onChange={e=>setAuth({...auth,password:e.target.value})} placeholder="8 caractères minimum"/><button type="button" className="password-visibility" onClick={()=>setShowPassword(v=>!v)} aria-label={showPassword?"Masquer le mot de passe":"Afficher le mot de passe"} aria-pressed={showPassword}>{showPassword?<EyeOff size={18}/>:<Eye size={18}/>}</button></div></Field>}{(authMode!=='signup'||signupStep===2)&&<Button disabled={busy||!configured}>{busy?'Patiente…':authMode==='login'?'Se connecter':authMode==='signup'?'Créer mon compte':authMode==='reset'?'Envoyer le lien':'Enregistrer le nouveau mot de passe'} <ArrowRight size={17}/></Button>}</form>{authMode==='login'&&<button className="text-button" type="button" onClick={()=>setAuthMode('reset')}>Mot de passe oublié ?</button>}{(authMode==='reset'||authMode==='recovery')&&<button className="text-button" type="button" onClick={()=>setAuthMode('login')}>Retour à la connexion</button>}{!configured&&<Notice type="error">Connexion indisponible : variables Supabase manquantes.</Notice>}<small className="legal-note">En continuant, tu acceptes les règles d’utilisation et la politique de confidentialité de SAVOIR+.</small></div></main>}

    {currentPage==='create'&&<main className="container page-main"><div className="page-intro"><span className="eyebrow">ESPACE CRÉATEUR</span><h1>Faites de votre savoir une ressource.</h1><p>Créez votre boutique, publiez vos ressources et suivez vos clients et vos ventes.</p></div>{!session?<div className="callout"><GraduationCap size={28}/><div><b>Connecte-toi pour devenir créateur.</b><p>Tu pourras créer ton profil enseignant et soumettre tes premières ressources.</p></div><Button onClick={()=>navigate('/connexion')}>Connexion / Inscription</Button></div>:role!=='teacher'&&role!=='admin'?<div className="callout"><AlertCircle/><div><b>Ton compte actuel est un compte apprenant.</b><p>La création de ressources est réservée aux comptes enseignants. Contacte l’équipe si tu souhaites changer de profil.</p></div></div>:<div className="form-layout"><form className="panel form-stack" onSubmit={createListing}><div className="panel-heading"><div><span className="eyebrow">NOUVELLE PUBLICATION</span><h2>Créer une ressource</h2></div><span className="status-pill approved">Publication du produit</span></div><Field label="Titre de la ressource"><input required minLength="3" maxLength="160" value={productForm.title} onChange={e=>setProductForm({...productForm,title:e.target.value})} placeholder="Ex. Exercices corrigés de mathématiques"/></Field><Field label="Description"><textarea required rows="4" maxLength="4000" value={productForm.description} onChange={e=>setProductForm({...productForm,description:e.target.value})} placeholder="Présente le contenu, ses objectifs et ce que l’apprenant va découvrir…"/></Field><Field label="Catégorie"><select value={productForm.category_id} onChange={e=>setProductForm({...productForm,category_id:e.target.value})}><option value="">Choisir une catégorie</option>{categories.map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></Field><div className="two-fields"><Field label="Matière"><select value={productForm.subject} onChange={e=>setProductForm({...productForm,subject:e.target.value})}>{subjects.map(s=><option key={s}>{s}</option>)}</select></Field><Field label="Niveau"><select value={productForm.level} onChange={e=>setProductForm({...productForm,level:e.target.value})}>{levels.map(s=><option key={s}>{s}</option>)}</select></Field></div><div className="two-fields"><Field label="Format"><select value={productForm.kind} onChange={e=>setProductForm({...productForm,kind:e.target.value})}>{kinds.map(s=><option key={s}>{s}</option>)}</select></Field><Field label="Prix indicatif (FCFA)" hint="Les ressources à 0 FCFA peuvent être rejointes gratuitement. Les achats payants sont suspendus jusqu’à l’activation du prestataire."><input type="number" min="0" step="50" required value={productForm.price_xof} onChange={e=>setProductForm({...productForm,price_xof:e.target.value})}/></Field></div><Field label="Fichiers du produit" hint="Jusqu’à 20 PDF et 10 vidéos MP4. 100 Mo maximum par fichier. Les fichiers restent dans un stockage privé."><label className="upload-box"><UploadCloud size={24}/><b>Choisir plusieurs fichiers</b><small>{uploadFiles.length?`${uploadFiles.length} fichier(s) sélectionné(s) · ${uploadFiles.filter(x=>x.type==='application/pdf').length}/20 PDF · ${uploadFiles.filter(x=>x.type==='video/mp4').length}/10 vidéos`:'PDF / e-books et vidéos MP4'}</small><input type="file" hidden multiple accept="application/pdf,video/mp4" onChange={e=>{const next=Array.from(e.target.files||[]);setUploadFiles(next);setShareLinks(null);}}/></label>{uploadFiles.length>0&&<div className="file-list">{uploadFiles.map((file,index)=><div className="table-row" key={`${file.name}-${index}`}><span>{file.type==='application/pdf'?'📄':'🎬'} {file.name}</span><small>{(file.size/1024/1024).toFixed(1)} Mo</small><button type="button" className="text-button" onClick={()=>setUploadFiles(old=>old.filter((_,i)=>i!==index))}>Retirer</button></div>)}</div>}</Field><Button disabled={busy}>{busy?'Envoi des fichiers…':'Publier mon produit'} <ArrowRight size={17}/></Button>{shareLinks&&<div className="notice success"><b>Produit publié ! Partage ces liens :</b><p>Aperçu du produit</p><code>{shareLinks.preview}</code><Button type="button" kind="btn-soft btn-sm" onClick={()=>navigator.clipboard?.writeText(shareLinks.preview).then(()=>notify('Lien d’aperçu copié.','success'))}>Copier le lien d’aperçu</Button><p>Lien de paiement (activation après choix du prestataire)</p><code>{shareLinks.payment}</code><Button type="button" kind="btn-soft btn-sm" onClick={()=>navigator.clipboard?.writeText(shareLinks.payment).then(()=>notify('Lien de paiement copié.','success'))}>Copier le lien de paiement</Button></div>}</form><aside className="panel guide-panel"><ShieldCheck size={28}/><h3>Avant de publier</h3><ul><li>Publie uniquement des contenus dont tu détiens les droits.</li><li>Choisis le niveau et la matière adaptés.</li><li>Rédige une description claire et honnête.</li><li>Les contenus payants restent privés jusqu’à un achat confirmé.</li></ul><div className="commission-card"><span>Commission de plateforme proposée</span><b>20 %</b><small>À confirmer dans les paramètres commerciaux avant activation des paiements.</small></div></aside></div>}</main>}

    {false&&currentPage==='dashboard'&&<main className="container page-main"><div className="dashboard-heading"><div><span className="eyebrow">MON ESPACE</span><h1>Bonjour {profile?.display_name?.split(' ')[0]||'et bienvenue'} 👋</h1><p>Retrouve ici tes activités et tes informations.</p></div><span className="role-pill">{admin?'Administrateur':role==='teacher'?'Enseignant':role==='parent'?'Parent':'Apprenant'}</span></div>{!session?<Empty icon={LockKeyhole} title="Connecte-toi pour accéder à ton espace" text="Tes ressources, commandes et informations seront regroupées ici." action={<Button onClick={()=>navigate('/connexion')}>Se connecter</Button>}/>:<><div className="dashboard-nav"><button className="active"><LayoutDashboard/>Vue d’ensemble</button>{role==='teacher'&&<button onClick={()=>navigate('/devenir-enseignant')}><Plus/>Créer une ressource</button>}<button onClick={()=>navigate('/bibliotheque')}><Library/>Ma bibliothèque</button><button onClick={()=>navigate('/favoris')}><Heart/>Mes favoris</button><button onClick={()=>navigate('/notifications')}><Bell/>Notifications</button>{admin&&<button onClick={()=>navigate('/admin')}><ShieldCheck/>Administration</button>}</div>{role==='teacher'?<><div className="stats-cards"><div><span>Mes ressources</span><b>{teacherListings.length}</b><small><FileText size={14}/> Toutes publications</small></div><div><span>En attente</span><b>{teacherListings.filter(x=>x.status==='pending').length}</b><small><Clock3 size={14}/> À valider</small></div><div><span>Ressources publiées</span><b>{teacherListings.filter(x=>x.status==='approved').length}</b><small><BadgeCheck size={14}/> Visibles en ligne</small></div><div><span>Solde du portefeuille</span><b>{money(availableWallet)}</b><small><Wallet size={14}/> Selon les transactions enregistrées</small></div></div><div className="panel"><div className="panel-heading"><h2>Mes publications</h2><Button kind="btn-soft btn-sm" onClick={()=>navigate('/devenir-enseignant')}><Plus size={15}/> Nouvelle ressource</Button></div>{teacherListings.length?teacherListings.map(x=><div className="table-row" key={x.id}><div className="table-main"><b>{x.title}</b><small>{x.subject} · {x.level} · {money(x.price_xof)}</small></div><span className={`status-pill ${x.status}`}>{x.status==='pending'?'En attente':x.status==='approved'?'Publiée':x.status==='rejected'?'Refusée':'Brouillon'}</span></div>):<Empty icon={FileText} title="Aucune publication" text="Ta première ressource pourra être créée en quelques étapes." action={<Button onClick={()=>navigate('/devenir-enseignant')}>Créer une ressource</Button>}/>}</div><div className="panel"><div className="panel-heading"><h2>Historique du portefeuille</h2></div>{wallet.length?wallet.map(x=><div className="table-row" key={x.id}><div className="table-main"><b>{x.description||'Transaction'}</b><small>{new Date(x.created_at).toLocaleDateString('fr-FR')}</small></div><strong className={x.amount_xof>=0?'positive':'negative'}>{money(x.amount_xof)}</strong></div>):<p className="muted">Aucune transaction enregistrée pour le moment.</p>}</div><div className="panel"><div className="panel-heading"><h2>Demander un retrait</h2><span className="status-pill pending">Minimum 1 000 FCFA</span></div><form className="form-stack" onSubmit={requestWithdrawal}><div className="two-fields"><Field label="Montant (FCFA)"><input type="number" min="1000" step="100" required value={withdrawalForm.amount} onChange={e=>setWithdrawalForm({...withdrawalForm,amount:e.target.value})}/></Field><Field label="Méthode"><select value={withdrawalForm.method} onChange={e=>setWithdrawalForm({...withdrawalForm,method:e.target.value})}><option value="mobile_money">Mobile Money</option><option value="bank_transfer">Virement bancaire</option></select></Field></div><Field label={withdrawalForm.method==='mobile_money'?'Numéro Mobile Money':'Référence du compte bancaire'}><input required value={withdrawalForm.phone} onChange={e=>setWithdrawalForm({...withdrawalForm,phone:e.target.value})} placeholder={withdrawalForm.method==='mobile_money'?'+229…':'Coordonnées du compte'}/></Field><Button disabled={busy}>Envoyer la demande</Button></form><div className="panel-heading" style={{marginTop:22}}><h3>Mes demandes</h3></div>{withdrawals.map(w=><div className="table-row" key={w.id}><div className="table-main"><b>{money(w.amount_xof)}</b><small>{new Date(w.created_at).toLocaleDateString('fr-FR')}</small></div><span className={`status-pill ${w.status}`}>{w.status}</span></div>)}{!withdrawals.length&&<p className="muted">Aucune demande de retrait.</p>}</div></>:<><div className="stats-cards"><div><span>Mes commandes</span><b>{orders.length}</b><small><ShoppingBag size={14}/> Historique</small></div><div><span>Achats confirmés</span><b>{orders.filter(x=>x.status==='paid').length}</b><small><CheckCircle2 size={14}/> Commandes payées</small></div><div><span>Favoris</span><b>{favoriteIds.length}</b><small><Heart size={14}/> Ressources sauvegardées</small></div></div><div className="panel"><div className="panel-heading"><h2>Commandes récentes</h2><button className="text-button" onClick={()=>navigate('/bibliotheque')}>Ma bibliothèque <ArrowRight size={15}/></button></div>{orders.length?orders.map(o=><div className="table-row" key={o.id}><div className="table-main"><b>Commande #{o.id.slice(0,8).toUpperCase()}</b><small>{new Date(o.created_at).toLocaleDateString('fr-FR')} · {money(o.subtotal_xof)}</small></div><span className={`status-pill ${o.status}`}>{o.status==='paid'?'Payée':o.status==='pending'?'En attente':'Échec'}</span></div>):<Empty icon={ShoppingBag} title="Aucune commande" text="Les ressources que tu achèteras apparaîtront ici." action={<Button kind="btn-outline" onClick={()=>navigate('/explorer')}>Explorer les ressources</Button>}/>}</div></>}</>}</main>}

    {false&&currentPage==='library'&&<main className="container page-main"><div className="page-intro"><span className="eyebrow">ESPACE APPRENANT</span><h1>Ma bibliothèque</h1><p>Retrouve les ressources associées à tes commandes payées.</p></div>{!session?<Empty icon={LockKeyhole} title="Connecte-toi pour accéder à ta bibliothèque" text="Tes achats confirmés seront disponibles ici." action={<Button onClick={()=>navigate('/connexion')}>Connexion</Button>}/>:<div className="panel">{orders.filter(o=>o.status==='paid').length?orders.filter(o=>o.status==='paid').map(o=>(o.order_items||[]).map(i=><div className="table-row" key={i.id}><div className="table-main"><b>{i.title_snapshot}</b><small>{money(i.unit_price_xof)} · Commande #{o.id.slice(0,8)}</small></div><Button kind="btn-soft btn-sm" onClick={()=>downloadResource(i.listing_id)} disabled={busy}><Download size={14}/> Télécharger</Button></div>)): <Empty icon={Library} title="Ta bibliothèque est encore vide" text="Seuls les achats confirmés apparaîtront ici. Les accès aux fichiers seront délivrés de manière sécurisée." action={<Button kind="btn-outline" onClick={()=>navigate('/explorer')}>Explorer les ressources</Button>}/>}</div>}</main>}

    {['dashboard','library','studio','course','parents','messages','teacher-profile','teachers','child-progress'].includes(currentPage)&&<WorkspaceRouter page={currentPage} path={path} session={session} profile={profile} role={role} notify={notify} navigate={navigate} openProduct={openProduct}/> }

    {currentPage==='favorites'&&<main className="container page-main"><div className="page-intro"><span className="eyebrow">MES SÉLECTIONS</span><h1>Mes favoris</h1></div>{!session?<Empty icon={LockKeyhole} title="Connecte-toi pour voir tes favoris" text="Enregistre les ressources qui t’intéressent." action={<Button onClick={()=>navigate('/connexion')}>Connexion</Button>}/>:products.filter(p=>favoriteIds.includes(p.id)).length?<div className="product-grid">{products.filter(p=>favoriteIds.includes(p.id)).map(p=><ProductCard key={p.id} item={p} onOpen={openProduct} onFavorite={toggleFavorite} favorite/>)}</div>:<Empty icon={Heart} title="Aucun favori pour le moment" text="Appuie sur le cœur d’une ressource pour la retrouver ici." action={<Button kind="btn-outline" onClick={()=>navigate('/explorer')}>Explorer</Button>}/>}</main>}

    {currentPage==='notifications'&&<main className="container page-main"><div className="page-intro"><span className="eyebrow">CENTRE DE NOTIFICATIONS</span><h1>Mes notifications</h1></div>{!session?<Empty icon={LockKeyhole} title="Connecte-toi pour voir tes notifications" text="Les mises à jour de ton compte apparaîtront ici." action={<Button onClick={()=>navigate('/connexion')}>Connexion</Button>}/>:notifications.length?<div className="panel">{notifications.map(n=><button className={`notification-row ${n.read_at?'read':''}`} key={n.id} onClick={()=>markNotification(n.id)}><span className="notification-icon"><Bell size={17}/></span><span className="notification-text"><b>{n.title}</b><small>{n.body}</small><time>{new Date(n.created_at).toLocaleString('fr-FR')}</time></span>{!n.read_at&&<i/>}</button>)}</div>:<Empty icon={Bell} title="Tout est calme" text="Tu verras ici les informations importantes de ton compte."/>}</main>}

    {currentPage==='admin'&&<main className="container page-main admin-page"><div className="dashboard-heading"><div><span className="eyebrow">CENTRE DE CONTRÔLE</span><h1>Administration SAVOIR+</h1><p>Vue d’ensemble de la plateforme, modération et suivi commercial.</p></div><span className="admin-secure"><ShieldCheck size={16}/> Accès protégé</span></div>{!session?<Empty icon={LockKeyhole} title="Connexion administrateur requise" text="Connecte-toi avec le compte auquel le rôle SAVOIR+ administrateur a été attribué." action={<Button onClick={()=>navigate('/connexion')}>Se connecter</Button>}/>:!admin?<Empty icon={ShieldCheck} title="Accès non autorisé" text="Ce compte ne possède pas le rôle administrateur SAVOIR+."/>:<><div className="admin-tabs">{[['overview','Vue générale'],['listings','Publications'],['sales','Ventes'],['learning','Apprentissage'],['categories','Catégories'],['users','Utilisateurs'],['reports','Signalements'],['journal','Journal d’activité']].map(([id,label])=><button key={id} className={adminTab===id?'active':''} onClick={()=>setAdminTab(id)}>{label}</button>)}</div>{adminTab==='overview'&&<><div className="stats-cards admin-stats"><div><span>Utilisateurs</span><b>{adminData.users.length}</b><small><Users size={14}/> Comptes enregistrés</small></div><div><span>Produits publiés</span><b>{adminData.pending.filter(x=>x.status==='approved').length}</b><small><BadgeCheck size={14}/> Visibles sur la marketplace</small></div><div><span>Inscriptions pédagogiques</span><b>{adminData.enrollments.length}</b><small><BookOpen size={14}/> Ressources rejointes</small></div><div><span>Consultations</span><b>{adminData.views.length}</b><small><Eye size={14}/> Vues authentifiées</small></div><div><span>Quiz réalisés</span><b>{adminData.quizAttempts.length}</b><small><CheckCircle2 size={14}/> Tentatives enregistrées</small></div></div><div className="admin-two"><div className="panel"><div className="panel-heading"><h2>Publications récentes</h2><button className="text-button" onClick={()=>setAdminTab('listings')}>Toutes les publications <ArrowRight size={15}/></button></div>{adminData.pending.slice(0,5).map(x=><div className="table-row" key={x.id}><div className="table-main"><b>{x.title}</b><small>{x.profiles?.display_name||'Enseignant'} · {money(x.price_xof)}</small></div><span className={`status-pill ${x.status==='approved'?'approved':'pending'}`}>{x.status==='approved'?'Publiée':x.status==='rejected'?'Refusée':'Brouillon'}</span></div>)}{!adminData.pending.length&&<p className="muted">Aucune publication en attente.</p>}</div><div className="panel"><div className="panel-heading"><h2>Inscriptions récentes</h2><button className="text-button" onClick={()=>setAdminTab('learning')}>Tout voir <ArrowRight size={15}/></button></div>{adminData.enrollments.slice(0,5).map(x=><div className="table-row" key={x.id}><div className="table-main"><b>{x.profiles?.display_name||'Apprenant'}</b><small>{x.listings?.title||'Ressource'} · {new Date(x.enrolled_at).toLocaleDateString('fr-FR')}</small></div><span className="status-pill approved">{x.source==='free'?'Gratuit':x.source}</span></div>)}{!adminData.enrollments.length&&<p className="muted">Aucune inscription pour le moment.</p>}</div></div></>}
      {adminTab==='listings'&&<div className="panel"><div className="panel-heading"><h2>Toutes les publications</h2><span>{adminData.pending.length} ressource(s)</span></div>{adminData.pending.length?adminData.pending.map(x=><div className="table-row" key={x.id}><div className="table-main"><b>{x.title}</b><small>{x.profiles?.display_name||'Créateur'} · {x.subject} · {x.level} · {x.kind}</small><small>{money(x.price_xof)} · {new Date(x.created_at).toLocaleString('fr-FR')}</small></div><span className={`status-pill ${x.status==='approved'?'approved':'pending'}`}>{x.status==='approved'?'Publiée':x.status==='pending'?'En attente historique':x.status}</span></div>):<Empty icon={BookOpen} title="Aucune publication" text="Les ressources créées par les vendeurs apparaîtront ici dès leur publication."/>}</div>}{adminTab==='sales'&&<div className="panel"><div className="panel-heading"><h2>Ventes et commandes</h2><span>{adminData.orders.length} commande(s)</span></div>{adminData.orderItems.length?adminData.orderItems.map(item=>{const order=adminData.orders.find(o=>o.id===item.order_id);if(!order)return null;const buyer=adminData.users.find(u=>u.user_id===order.buyer_id);const seller=adminData.users.find(u=>u.user_id===item.seller_id);return <div className="table-row" key={item.id}><div className="table-main"><b>{item.title_snapshot}</b><small>Acheteur : {buyer?.display_name||'Client'} · {buyer?.email||'E-mail non disponible'}</small><small>Créateur : {seller?.display_name||'Créateur'} · {seller?.email||'E-mail non disponible'}</small><small>{new Date(order.created_at).toLocaleString('fr-FR')}</small></div><strong>{money(item.unit_price_xof)}</strong><span className={order.status==='paid'?'status-pill approved':'status-pill pending'}>{order.status==='paid'?'Payée':order.status==='pending'?'En attente':order.status}</span></div>}) : <Empty icon={ShoppingBag} title="Aucune commande enregistrée" text="Les ventes apparaîtront ici après l’activation des paiements et les premiers achats confirmés."/>}</div>}{adminTab==='learning'&&<div className="admin-two"><div className="panel"><div className="panel-heading"><h2>Inscriptions aux ressources</h2><span>{adminData.enrollments.length}</span></div>{adminData.enrollments.length?adminData.enrollments.slice(0,200).map(e=><div className="table-row" key={e.id}><div className="table-main"><b>{e.profiles?.display_name||'Apprenant'}</b><small>{e.listings?.title||'Ressource'} · {new Date(e.enrolled_at).toLocaleDateString('fr-FR')}</small></div><span className="status-pill approved">{e.source==='free'?'Gratuit':e.source}</span></div>):<Empty icon={BookOpen} title="Aucune inscription" text="Les inscriptions gratuites et les accès accordés apparaîtront ici."/>}</div><div className="panel"><div className="panel-heading"><h2>Résultats des quiz</h2><span>{adminData.quizAttempts.length}</span></div>{adminData.quizAttempts.length?adminData.quizAttempts.slice(0,200).map(a=><div className="table-row" key={a.id}><div className="table-main"><b>{a.profiles?.display_name||'Apprenant'}</b><small>{a.quizzes?.title||'Quiz'} · {new Date(a.submitted_at).toLocaleDateString('fr-FR')}</small></div><strong>{Number(a.percentage).toFixed(0)} %</strong><span className={`status-pill ${a.passed?'approved':'pending'}`}>{a.passed?'Réussi':'À reprendre'}</span></div>):<Empty icon={CheckCircle2} title="Aucun quiz rendu" text="Les résultats s’afficheront après les premières évaluations."/>}</div></div>}
      {adminTab==='categories'&&<div className="panel"><div className="panel-heading"><h2>Gérer les catégories</h2><span>{adminData.categories.length} catégorie(s)</span></div><form className="form-stack" onSubmit={createCategory}><div className="two-fields"><Field label="Nom de la catégorie"><input required value={categoryForm.name} onChange={e=>setCategoryForm({...categoryForm,name:e.target.value})} placeholder="Ex. Examens et concours"/></Field><Field label="Slug (facultatif)"><input value={categoryForm.slug} onChange={e=>setCategoryForm({...categoryForm,slug:e.target.value})} placeholder="examens-concours"/></Field></div><Field label="Description"><input value={categoryForm.description} onChange={e=>setCategoryForm({...categoryForm,description:e.target.value})} placeholder="Décris les ressources de cette catégorie"/></Field><Button>Ajouter la catégorie <Plus size={15}/></Button></form><div className="studio-list">{adminData.categories.map(c=><div className="studio-item" key={c.id}><div><b>{c.name}</b><small>{c.slug} · {c.description}</small></div><Button kind="btn-danger btn-sm" onClick={()=>deleteCategory(c.id)}>Supprimer</Button></div>)}</div></div>}
      {adminTab==='journal'&&<div className="panel"><div className="panel-heading"><h2>Journal des actions administratives</h2><span>{adminData.actions.length}</span></div>{adminData.actions.length?adminData.actions.map(a=><div className="table-row" key={a.id}><div className="table-main"><b>{a.action}</b><small>{a.target_type} · {a.profiles?.display_name||'Administrateur'} · {new Date(a.created_at).toLocaleString('fr-FR')}</small></div><span>{a.target_id?.slice(0,8)||'—'}</span></div>):<Empty icon={ShieldCheck} title="Aucune action journalisée" text="Les décisions de modération et les opérations sensibles seront consignées ici."/>}</div>}
      {adminTab==='orders'&&<div className="panel"><div className="panel-heading"><h2>Toutes les commandes</h2></div>{adminData.orders.map(o=><div className="table-row" key={o.id}><div className="table-main"><b>Commande #{o.id.slice(0,8).toUpperCase()}</b><small>{new Date(o.created_at).toLocaleString('fr-FR')} · Acheteur {o.buyer_id.slice(0,8)}</small></div><strong>{money(o.subtotal_xof)}</strong><span className={`status-pill ${o.status}`}>{o.status}</span></div>)}{!adminData.orders.length&&<Empty icon={ShoppingBag} title="Aucune commande" text="Les commandes réelles apparaîtront ici."/>}</div>}
      {adminTab==='payments'&&<div className="panel"><div className="panel-heading"><h2>Suivi des paiements</h2></div><Notice>Les paiements en ligne ne sont pas encore activés. Cette page affichera les transactions après configuration du prestataire et validation sécurisée des notifications serveur.</Notice>{adminData.payments.map(p=><div className="table-row" key={p.id}><div className="table-main"><b>{p.provider_reference||p.id.slice(0,8)}</b><small>{p.provider} · {new Date(p.created_at).toLocaleString('fr-FR')}</small></div><strong>{money(p.amount_xof)}</strong><span className={`status-pill ${p.status}`}>{p.status}</span></div>)}</div>}
      {adminTab==='withdrawals'&&<div className="panel"><div className="panel-heading"><h2>Demandes de retrait</h2></div>{adminData.withdrawals.map(w=><div className="table-row" key={w.id}><div className="table-main"><b>{money(w.amount_xof)}</b><small>{w.payout_method} · Enseignant {w.teacher_id.slice(0,8)}</small></div><span className={`status-pill ${w.status}`}>{w.status}</span>{w.status!=='paid'&&w.status!=='rejected'&&<><Button kind="btn-soft btn-sm" onClick={()=>updateWithdrawal(w.id,'processing')}>Traiter</Button><Button kind="btn-success btn-sm" onClick={()=>updateWithdrawal(w.id,'paid')}>Payé</Button><Button kind="btn-danger btn-sm" onClick={()=>updateWithdrawal(w.id,'rejected')}>Refuser</Button></>}</div>)}{!adminData.withdrawals.length&&<Empty icon={Wallet} title="Aucun retrait demandé" text="Les demandes des enseignants seront suivies ici."/>}</div>}
      {adminTab==='users'&&<div className="panel"><div className="panel-heading"><h2>Utilisateurs</h2><span>{adminData.users.length} comptes</span></div>{adminData.users.map(u=>{const sales=adminData.orderItems.filter(x=>x.seller_id===u.user_id&&adminData.orders.some(o=>o.id===x.order_id&&o.status==='paid')).reduce((sum,x)=>sum+Number(x.teacher_amount_xof||0),0);const balance=adminData.walletTransactions.filter(x=>x.teacher_id===u.user_id).reduce((sum,x)=>sum+Number(x.amount_xof||0),0);return <div className="table-row admin-user-row" key={u.user_id}><div className="table-main"><b>{u.display_name||'Sans nom'}</b><small>{u.email} · {u.country||'Pays non précisé'} · {u.account_type==='teacher'?'Créateur':u.account_type==='parent'?'Parent':u.learner_kind==='university_student'?'Étudiant':'Élève'}</small><small>{u.phone||'Téléphone non renseigné'} · {u.city||'Ville non renseignée'} · {u.birth_year?`Né(e) en ${u.birth_year}`:''} · {u.school_class||u.child_class||u.university_year||u.study_field||'Parcours non renseigné'}</small><small>{u.signup_goal?`Objectif : ${u.signup_goal}`:''} {u.store_name?`· Boutique : ${u.store_name}`:''} {u.teacher_subjects?.length?`· Matières : ${u.teacher_subjects.join(', ')}`:''} {u.teacher_levels?.length?`· Niveaux : ${u.teacher_levels.join(', ')}`:''}</small><small>Ventes confirmées : {money(sales)} · Solde comptabilisé : {money(balance)}</small></div><span className="role-pill">{u.app_role==='savoir_admin'?'Administrateur':u.account_type==='teacher'?'Créateur':u.account_type==='parent'?'Parent':u.learner_kind==='university_student'?'Étudiant':'Élève'}</span>{isPlatformOwner&&u.app_role!=='savoir_admin'&&u.account_type==='teacher'&&<Button kind="btn-outline btn-sm" onClick={()=>promoteAdmin(u.user_id)}>Nommer admin</Button>}</div>})}</div>}
      {adminTab==='reports'&&<div className="panel"><div className="panel-heading"><h2>Signalements</h2><span>{adminData.reports.length} dossier(s)</span></div>{adminData.reports.map(r=><div className="moderation-item" key={r.id}><div><b>{r.reason==='content'?'Contenu inapproprié':r.reason==='copyright'?'Droits d’auteur':r.reason==='spam'?'Spam':r.reason==='abuse'?'Comportement abusif':r.reason}</b><p>{r.details||'Aucun détail fourni.'}</p><small>{new Date(r.created_at).toLocaleString('fr-FR')} · {r.listing_id?'Ressource '+r.listing_id.slice(0,8):'Utilisateur signalé'}</small></div><div className="moderation-actions"><span className={`status-pill ${r.status}`}>{r.status}</span>{r.status!=='resolved'&&<Button kind="btn-soft btn-sm" onClick={()=>moderateReport(r.id,'resolved')}>Résolu</Button>}{r.status!=='dismissed'&&<Button kind="btn-danger btn-sm" onClick={()=>moderateReport(r.id,'dismissed')}>Classer sans suite</Button>}{r.status==='open'&&<Button kind="btn-outline btn-sm" onClick={()=>moderateReport(r.id,'reviewing')}>Prendre en charge</Button>}</div></div>)}{!adminData.reports.length&&<Empty icon={ShieldCheck} title="Aucun signalement" text="Les signalements reçus seront visibles ici."/>}</div>}
    </>}</main>}

    <footer className="site-footer"><div className="container footer-grid"><div><div className="brand footer-brand"><span className="brand-symbol">S+</span><span>SAVOIR<span className="brand-plus">+</span></span></div><p>Votre savoir a plus de valeur.</p></div><div><b>Explorer</b><button onClick={()=>navigate('/explorer')}>Ressources</button><button onClick={()=>navigate('/explorer')}>Matières et niveaux</button></div><div><b>Contribuer</b><button onClick={()=>navigate('/devenir-enseignant')}>Devenir créateur</button><button onClick={()=>navigate('/connexion')}>Créer un compte</button></div><div><b>Mon espace</b><button onClick={()=>navigate('/mon-espace')}>Tableau de bord</button><button onClick={()=>navigate('/admin')}>Administration</button></div></div><div className="container footer-bottom"><span>© {new Date().getFullYear()} SAVOIR+. Tous droits réservés.</span><span>Plateforme éducative · Ouverte à l’international</span></div></footer>

    {selected&&<div className="modal-backdrop" onClick={()=>setSelected(null)}><div className="product-modal" onClick={e=>e.stopPropagation()}><button className="modal-close" onClick={()=>setSelected(null)}><X/></button><div className="modal-art"><span>{kindEmoji[selected.kind]||'📘'}</span></div><span className="eyebrow">{selected.subject} · {selected.level}</span><h2>{selected.title}</h2><p>{selected.description}</p><div className="teacher-line"><span className="avatar">{initials(selected.teacher)}</span><div><b>{selected.teacher}</b><small>Créateur SAVOIR+</small></div></div><div className="modal-price"><strong>{Number(selected.price_xof)===0?'Gratuit':money(selected.price_xof)}</strong><span>{Number(selected.price_xof)===0?'Inscription gratuite · aucun paiement requis':'Achat suspendu pendant la configuration des paiements'}</span></div>{Number(selected.price_xof)>0&&<Notice>{path.startsWith('/payer/')?'Le lien de paiement est prêt, mais aucun paiement ne sera encaissé avant le branchement et les tests du prestataire.':'Cette ressource est visible dans le catalogue, mais son achat sera activé après la configuration du prestataire.'} Aucun débit ne sera effectué pour le moment.</Notice>}<div className="modal-actions"><Button disabled={busy||(Number(selected.price_xof)>0&&path.startsWith('/payer/'))} onClick={()=>Number(selected.price_xof)===0?createOrder(selected):navigate(`/payer/${selected.id}`)}>{Number(selected.price_xof)===0?'Accéder gratuitement':path.startsWith('/payer/')?'Paiement bientôt disponible':'Payer'}</Button><Button kind="btn-outline" onClick={()=>toggleFavorite(selected)}><Heart size={16}/> Favoris</Button>{session&&selected.seller_id!==session.user.id&&<Button kind="btn-outline" onClick={()=>navigate(`/messages?to=${selected.seller_id}`)}><MessageSquare size={15}/> Contacter le créateur</Button>}{session&&<Button kind="btn-ghost" onClick={()=>setReportOpen(v=>!v)}><AlertCircle size={15}/> Signaler</Button>}</div>{reportOpen&&session&&<form className="form-stack report-form" onSubmit={submitReport}><Field label="Motif du signalement"><select value={reportForm.reason} onChange={e=>setReportForm({...reportForm,reason:e.target.value})}><option value="content">Contenu inapproprié ou incorrect</option><option value="copyright">Droits d’auteur / contenu copié</option><option value="spam">Spam ou publicité abusive</option><option value="abuse">Comportement abusif</option><option value="other">Autre</option></select></Field><Field label="Précisions (facultatif)"><textarea rows="3" maxLength="2000" value={reportForm.details} onChange={e=>setReportForm({...reportForm,details:e.target.value})} placeholder="Explique le problème observé…"/></Field><Button disabled={busy}>Envoyer le signalement</Button></form>}</div></div>}
  </div>;
}
